  "@type": "FAQPage",
  "inLanguage": "en",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What must a certificate of analysis for an API or excipient contain?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It must identify the material, grade and pharmacopoeial edition; the batch number with its manufacture and retest or expiry dates; the manufacturer and the site that made and tested it; every test in the agreed specification with its acceptance criterion and actual result; and a dated release by a named person in the quality unit."
      }
    },
    {
      "@type": "Question",
      "name": "Is a certificate of analysis from a distributor acceptable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A distributor may issue its own covering certificate, but the manufacturer's original certificate should travel with it unchanged. Only the original names the site that made and tested the batch and the quality unit that released it. A distributor's certificate on its own tells you who sold the material, not who produced it or tested it."
      }
    },
    {
      "@type": "Question",
      "name": "Should every result on a certificate be a number?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Tests that are pass or fail by nature, such as appearance and identification, can be reported as complies. Tests that produce a value, such as assay, water content or a named impurity, should report the value with its unit, so that the buyer can see how close the batch sits to its acceptance criterion."
      }
    },
    {
      "@type": "Question",
      "name": "Does a certificate of analysis need to include raw data?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Not normally. A certificate summarises the results; chromatograms, raw data and method validation stay in the manufacturer's batch records. A buyer can ask for supporting data when a result looks unusual, or review it during an audit, and a quality agreement can set out when the manufacturer must provide it."
      }
    },
    {
      "@type": "Question",
      "name": "What should an excipient certificate add that an API certificate may not?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "An excipient certificate should state the pharmaceutical grade clearly, because the same substance is often made in food and technical grades too. It should also report the functional properties that matter for your formulation, such as particle size or viscosity, where your specification controls them."
      }
    }
  ]
